{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C02", "C15", "C21", "C29", "C31", "C33", "C40", "C46", "C60", "C61", "C62", "C63", "C64", "C65", "C66", "C68", "C69", "C70", "C71"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C02", "C15", "C21", "C40", "C46", "C63", "C68", "C70"],
  "claims": [
    {
      "claim": "L5 confirms PEPT1-mediated absorptive transport for the aminocephalosporin class: cefadroxil (C63), cephalexin (C70), and ceftibuten (C68) are PEPT1 substrates. Cefatrizine shares the alpha-amino-p-hydroxyphenylglycyl side chain with cefadroxil and amoxicillin, which is the canonical PEPT1 recognition motif.",
      "card_ids": ["C63", "C70", "C68"]
    },
    {
      "claim": "Meropenem Caco-2 records show absorptive Papp A to B of 2.63 to 2.92 times 10^-6 cm/s (C61, C62, C65, C69, C71) with B to A of 1.47 times 10^-6 cm/s (C66), giving no net efflux. This shows beta-lactams can achieve meaningful carrier-mediated permeability despite extreme polarity.",
      "card_ids": ["C61", "C62", "C65", "C66", "C69", "C71"]
    },
    {
      "claim": "Ceftibuten intra-intestinal administration produced higher Cmax and AUC at the circadian peak of intestinal PEPT1 expression (C68), directly linking PEPT1 transporter activity to systemic exposure for a beta-lactam.",
      "card_ids": ["C68"]
    },
    {
      "claim": "Prior direct evidence remains decisive: baclofen absolute F is 73 to 86 percent in humans (C02, C15, C21), levodopa absolute F is 63.6 to 86.4 percent across fasted and fed IR and CR formulations (C29, C31, C33), and oral beta-lactam exposure is meaningful with ampicillin Cmax 9.53 µg/mL after 500 mg sultamicillin (C40) and amoxicillin Cmax 11.4 µg/mL after 200 mg in dogs (C46).",
      "card_ids": ["C02", "C15", "C21", "C29", "C31", "C33", "C40", "C46"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C60", "C61", "C62", "C63", "C64", "C65", "C66", "C68", "C69", "C70", "C71"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for cefatrizine is present in the supplied cards.",
    "No direct cefatrizine PEPT1, Caco-2, or gut-wall metabolism assay is supplied; L5 records are analog-based.",
    "L3 Cmax records lack matched IV AUC, so they do not quantify absolute F.",
    "No direct cefatrizine efflux or intestinal metabolism data are available.",
    "Species, formulation, and prandial differences prevent a numeric F estimate."
  ],
  "decision_summary": "L5 adds mechanistic support for PEPT1-mediated absorption of aminocephalosporins carrying the alpha-amino-p-hydroxyphenylglycyl side chain, which is the cefatrizine scaffold. Meropenem records show absorptive permeability without net efflux, and ceftibuten links PEPT1 activity to systemic exposure. No affirmative threshold-relevant evidence supports F below 20 percent. The prediction remains high and is strengthened, with moderate confidence because no direct cefatrizine F measurement exists."
}

